mapper.select:
SELECT id, template_name, template_type, module_code, version, file_id, is_default, default_scope_key, status, created_at, updated_at
FROM sys_import_export_template
WHERE id = #{id}

SELECT id, template_name, template_type, module_code, version, file_id, is_default, default_scope_key, status, created_at, updated_at
FROM sys_import_export_template
WHERE module_code = #{moduleCode}
  AND template_type = #{templateType}
  AND version = #{version}

SELECT id, template_name, template_type, module_code, version, file_id, is_default, default_scope_key, status, created_at, updated_at
FROM sys_import_export_template
WHERE module_code = #{moduleCode}
  AND template_type = #{templateType}
  AND is_default = 1
  AND status = 'ENABLED'
